pub type Config = { host: Str; port: Int; secret: Str; }

impl Debug for Config {
  fn fmt(self: &Config, f: &mut Formatter) -> Result[(), FmtError] {
    return f.debug_struct("Config")
      .field("host", &self.host)
      .field("port", &self.port)
      .field("secret", &"***")
      .finish();
  }
}

fn main() -> Int {
  let c = Config{ host: "localhost", port: 8080, secret: "abc123" };
  return c.port;
}
